func TestDecodeFloatForms(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{name: "simple", input: "3.14", want: "3.14"},
		{name: "zero", input: "0.0", want: "0"},
		{name: "negative zero", input: "-0.0", want: "-0"},
		{name: "explicit plus", input: "+1.5", want: "1.5"},
