package toml

import (
	"strings"
)

// maxScalar is the largest Unicode code point, U+10FFFF.
const maxScalar = 0x10FFFF

// simpleEscapes are the one-character escapes TOML v1.0.0 lists for basic strings.
var simpleEscapes = map[byte]string{
	'b':  "\b",
	't':  "\t",
	'n':  "\n",
	'f':  "\f",
	'r':  "\r",
	'"':  "\"",
	'\\': "\\",
}

// basicString reads a single-line basic string at p.pos, which holds the opening quote.
func (p *parser) basicString() (string, error) {
	p.pos++
	var b strings.Builder
	for {
		if p.done() || p.atNewline() {
			return "", p.errorf("unterminated basic string")
		}
		c := p.src[p.pos]
		switch {
		case c == '"':
			p.pos++
			return b.String(), nil
		case c == '\\':
			s, err := p.escape()
			if err != nil {
				return "", err
			}
			b.WriteString(s)
		case isDisallowedControl(c):
			return "", p.errorf("control character in basic string")
		default:
			b.WriteByte(c)
			p.pos++
		}
	}
}

// literalString reads a single-line literal string at p.pos, which holds the opening
// quote. Nothing inside is escaped.
func (p *parser) literalString() (string, error) {
	p.pos++
	start := p.pos
	for !p.done() && p.src[p.pos] != '\'' {
		if p.atNewline() || isDisallowedControl(p.src[p.pos]) {
			return "", p.errorf("invalid character in literal string")
		}
		p.pos++
	}
	if p.done() {
		return "", p.errorf("unterminated literal string")
	}
	s := p.src[start:p.pos]
	p.pos++
	return s, nil
}

// multiline reads a multi-line string whose delimiter is quote repeated three times.
// Escapes apply only when escapes is true, which is the basic form. A line break right
// after the opening delimiter is trimmed. Up to two extra quotes may sit directly before
// the closing delimiter.
func (p *parser) multiline(quote byte, escapes bool) (string, error) {
	p.pos += 3
	p.trimOpeningNewline()
	var b strings.Builder
	for {
		if p.done() {
			return "", p.errorf("unterminated multi-line string")
		}
		c := p.src[p.pos]
		switch {
		case c == quote:
			run := p.quoteRun(quote)
			if run < 3 {
				b.WriteString(p.src[p.pos : p.pos+run])
				p.pos += run
				continue
			}
			if run > 5 {
				return "", p.errorf("too many quotes closing multi-line string")
			}
			b.WriteString(p.src[p.pos : p.pos+run-3])
			p.pos += run
			return b.String(), nil
		case escapes && c == '\\' && p.lineEndingBackslash():
			p.skipLineEnding()
		case escapes && c == '\\':
			s, err := p.escape()
			if err != nil {
				return "", err
			}
			b.WriteString(s)
		case p.atCRLF():
			b.WriteString("\r\n")
			p.pos += 2
		case c == '\n':
			b.WriteByte(c)
			p.pos++
		case isDisallowedControl(c):
			return "", p.errorf("control character in multi-line string")
		default:
			b.WriteByte(c)
			p.pos++
		}
	}
}

// escape decodes the escape sequence whose backslash is at p.pos. Only the escapes
// TOML v1.0.0 lists are accepted; any other escape is a syntax error.
func (p *parser) escape() (string, error) {
	p.pos++
	if p.done() {
		return "", p.errorf("unterminated escape")
	}
	c := p.src[p.pos]
	if s, ok := simpleEscapes[c]; ok {
		p.pos++
		return s, nil
	}
	switch c {
	case 'u':
		return p.unicodeEscape(4)
	case 'U':
		return p.unicodeEscape(8)
	}
	return "", p.errorf("unknown escape \\%c", c)
}

// unicodeEscape decodes the digits after \u (digits is 4) or \U (digits is 8). The
// code point must be a Unicode scalar value: at most U+10FFFF and not a surrogate.
func (p *parser) unicodeEscape(digits int) (string, error) {
	start := p.pos + 1
	end := start + digits
	if end > len(p.src) {
		return "", p.errorf("unicode escape needs %d hex digits", digits)
	}
	var code uint32
	for i := start; i < end; i++ {
		v, ok := hexValue(p.src[i])
		if !ok {
			return "", p.errorf("unicode escape needs %d hex digits", digits)
		}
		code = code<<4 | v
	}
	if code > maxScalar || (code >= 0xD800 && code <= 0xDFFF) {
		return "", p.errorf("unicode escape %X is not a Unicode scalar value", code)
	}
	p.pos = end
	return string(rune(code)), nil
}

// lineEndingBackslash reports whether the backslash at p.pos ends a line. Only spaces
// and tabs may stand between it and the line break.
func (p *parser) lineEndingBackslash() bool {
	i := p.pos + 1
	for i < len(p.src) && (p.src[i] == ' ' || p.src[i] == '\t') {
		i++
	}
	return i < len(p.src) && (p.src[i] == '\n' || strings.HasPrefix(p.src[i:], "\r\n"))
}

// skipLineEnding consumes a line-ending backslash and every whitespace character
// after it, up to the next content.
func (p *parser) skipLineEnding() {
	p.pos++
	for !p.done() {
		switch {
		case p.src[p.pos] == ' ' || p.src[p.pos] == '\t' || p.src[p.pos] == '\n':
			p.pos++
		case p.atCRLF():
			p.pos += 2
		default:
			return
		}
	}
}

func (p *parser) trimOpeningNewline() {
	if p.atCRLF() {
		p.pos += 2
	} else if p.atNewline() {
		p.pos++
	}
}

// quoteRun counts the consecutive quote characters starting at p.pos.
func (p *parser) quoteRun(quote byte) int {
	n := 0
	for p.pos+n < len(p.src) && p.src[p.pos+n] == quote {
		n++
	}
	return n
}

func hexValue(c byte) (uint32, bool) {
	switch {
	case c >= '0' && c <= '9':
		return uint32(c - '0'), true
	case c >= 'a' && c <= 'f':
		return uint32(c-'a') + 10, true
	case c >= 'A' && c <= 'F':
		return uint32(c-'A') + 10, true
	}
	return 0, false
}

package toml

import (
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"
)

// Each pattern is the TOML v1.0.0 grammar for one form. Underscores sit only between
// digits, and leading zeros are allowed only in the fraction and exponent of a float.
var (
	decimalIntPattern   = regexp.MustCompile(`^[+-]?(0|[1-9](_?[0-9])*)$`)
	hexIntPattern       = regexp.MustCompile(`^0x[0-9A-Fa-f](_?[0-9A-Fa-f])*$`)
	octalIntPattern     = regexp.MustCompile(`^0o[0-7](_?[0-7])*$`)
	binaryIntPattern    = regexp.MustCompile(`^0b[01](_?[01])*$`)
	floatPattern        = regexp.MustCompile(`^[+-]?(0|[1-9](_?[0-9])*)((\.[0-9](_?[0-9])*)([eE][+-]?[0-9](_?[0-9])*)?|[eE][+-]?[0-9](_?[0-9])*)$`)
	specialFloatPattern = regexp.MustCompile(`^[+-]?(inf|nan)$`)
)

// scalar reads the bare token at p.pos and classifies it as a boolean, integer, or float.
// The whole token must match one grammar, so a partly valid token is rejected, not truncated.
func (p *parser) scalar() (map[string]any, error) {
	start := p.pos
	for !p.done() && isScalarByte(p.src[p.pos]) {
		p.pos++
	}
	token := p.src[start:p.pos]
	switch {
	case token == "":
		return nil, p.errorf("expected a value")
	case token == "true" || token == "false":
		return tagged("bool", token), nil
	case specialFloatPattern.MatchString(token):
		return tagged("float", formatFloat(parseSpecialFloat(token))), nil
	case isInteger(token):
		n, err := parseInteger(token)
		if err != nil {
			return nil, p.errorf("%v", err)
		}
		return tagged("integer", strconv.FormatInt(n, 10)), nil
	case floatPattern.MatchString(token):
		f, err := strconv.ParseFloat(stripUnderscores(token), 64)
		if err != nil {
			return nil, p.errorf("float %s is outside the binary64 range", token)
		}
		return tagged("float", formatFloat(f)), nil
	}
	return nil, p.errorf("invalid value %q", token)
}

// isScalarByte reports whether c can appear in a bare boolean, integer, or float token.
func isScalarByte(c byte) bool {
	return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ||
		c == '+' || c == '-' || c == '_' || c == '.'
}

func isInteger(token string) bool {
	return decimalIntPattern.MatchString(token) || hexIntPattern.MatchString(token) ||
		octalIntPattern.MatchString(token) || binaryIntPattern.MatchString(token)
}

// parseInteger converts a token that passed isInteger to a signed 64-bit value. A value
// outside that range is an error, never a rounded or wrapped result.
func parseInteger(token string) (int64, error) {
	digits := stripUnderscores(token)
	base := 10
	switch {
	case hexIntPattern.MatchString(token):
		base, digits = 16, digits[2:]
	case octalIntPattern.MatchString(token):
		base, digits = 8, digits[2:]
	case binaryIntPattern.MatchString(token):
		base, digits = 2, digits[2:]
	}
	n, err := strconv.ParseInt(digits, base, 64)
	if err != nil {
		return 0, fmt.Errorf("integer %s is outside the signed 64-bit range", token)
	}
	return n, nil
}

// parseSpecialFloat maps a token that passed specialFloatPattern to its IEEE 754 value.
func parseSpecialFloat(token string) float64 {
	switch {
	case strings.HasSuffix(token, "nan"):
		return math.NaN()
	case strings.HasPrefix(token, "-"):
		return math.Inf(-1)
	}
	return math.Inf(1)
}

// formatFloat renders a float as the shortest decimal that reads back to the same
// binary64 value. Special values use the TOML spelling without a leading plus.
func formatFloat(f float64) string {
	switch {
	case math.IsNaN(f):
		return "nan"
	case math.IsInf(f, 1):
		return "inf"
	case math.IsInf(f, -1):
		return "-inf"
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func stripUnderscores(token string) string {
	return strings.ReplaceAll(token, "_", "")
}

// tagged builds the {"type", "value"} model for a scalar whose value is already a string.
func tagged(kind, value string) map[string]any {
	return map[string]any{"type": kind, "value": value}
}

// Command toml-decoder reads a TOML document on stdin and writes its
// tagged-JSON description to stdout. Diagnostics go to stderr and malformed
// input exits non-zero.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/owner/toml-decoder/internal/toml"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "toml-decoder:", err)
		os.Exit(1)
	}
}

// run decodes the document on in and encodes the result as JSON to out.
func run(in io.Reader, out io.Writer) error {
	doc, err := toml.Decode(in)
	if err != nil {
		return fmt.Errorf("decode: %w", err)
	}
	return json.NewEncoder(out).Encode(doc)
}

